// ---- Mars Life Line style header (generated by scripts/kiln-style-sync.mjs from src/style/tokens.json, style v2) ----
// Paste at the top of every .kiln.js source. Do not edit colours here; edit tokens.json and re-run npm run style:sync.
const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----

const meta = {
  name: 'o2-canister',
  role: 'prop',
  reference: 'models and assets images/phase-4/o2-canister.png'
};

function build() {
  const root = createRoot('o2-canister');
  const m = styleMaterials();
  const N = 12; // 12-faceted cylinder matching reference image

  // -------------------------------------------------------------------------
  // 1. TANK BODY (Ivory satin finish with faceted chamfers)
  // -------------------------------------------------------------------------
  // Bottom chamfer
  createPart('TankBaseChamfer', cylinderGeo(0.13, 0.10, 0.05, N), m.panel, { position: [0, 0.025, 0], parent: root });

  // Lower ivory section
  createPart('TankLowerBody', cylinderGeo(0.13, 0.13, 0.07, N), m.panel, { position: [0, 0.085, 0], parent: root });

  // Lower orange band (raised chamfered ring)
  createPart('BandLowerMid', cylinderGeo(0.142, 0.142, 0.038, N), m.accent, { position: [0, 0.15, 0], parent: root });
  createPart('BandLowerChamferTop', cylinderGeo(0.13, 0.142, 0.012, N), m.accent, { position: [0, 0.175, 0], parent: root });
  createPart('BandLowerChamferBottom', cylinderGeo(0.142, 0.13, 0.012, N), m.accent, { position: [0, 0.125, 0], parent: root });

  // Middle ivory section
  createPart('TankMidBody', cylinderGeo(0.13, 0.13, 0.20, N), m.panel, { position: [0, 0.28, 0], parent: root });

  // Upper orange band (raised chamfered ring)
  createPart('BandUpperMid', cylinderGeo(0.142, 0.142, 0.038, N), m.accent, { position: [0, 0.41, 0], parent: root });
  createPart('BandUpperChamferTop', cylinderGeo(0.13, 0.142, 0.012, N), m.accent, { position: [0, 0.435, 0], parent: root });
  createPart('BandUpperChamferBottom', cylinderGeo(0.142, 0.13, 0.012, N), m.accent, { position: [0, 0.385, 0], parent: root });

  // Upper ivory section & shoulder chamfer
  createPart('TankUpperBody', cylinderGeo(0.13, 0.13, 0.04, N), m.panel, { position: [0, 0.46, 0], parent: root });
  createPart('TankShoulderChamfer', cylinderGeo(0.08, 0.13, 0.06, N), m.panel, { position: [0, 0.51, 0], parent: root });

  // -------------------------------------------------------------------------
  // 2. VALVE & SHROUD HANDLE (Dark slate/trim with grasp aperture)
  // -------------------------------------------------------------------------
  // Stepped mounting collar
  createPart('ValveFlange', cylinderGeo(0.068, 0.072, 0.015, 12), m.panelGray, { position: [0, 0.5475, 0], parent: root });
  createPart('ValveNeck', cylinderGeo(0.050, 0.055, 0.025, 12), m.trim, { position: [0, 0.5675, 0], parent: root });

  // Protective collar shroud with handle loop
  createPart('ShroudBase', cylinderGeo(0.065, 0.065, 0.016, 12), m.panelGray, { position: [0, 0.588, 0], parent: root });
  // Left & right handle posts
  createPart('ShroudPostL', cylinderGeo(0.016, 0.016, 0.035, 6), m.panelGray, { position: [0, 0.613, -0.044], parent: root });
  createPart('ShroudPostR', cylinderGeo(0.016, 0.016, 0.035, 6), m.panelGray, { position: [0, 0.613, 0.044], parent: root });
  // Top bridge / handle grip
  createPart('ShroudTopBridge', cylinderGeo(0.065, 0.065, 0.018, 12), m.panelGray, { position: [0, 0.639, 0], parent: root });

  // Inner valve regulator
  createPart('ValveRegulator', cylinderGeo(0.022, 0.022, 0.03, 8), m.trim, { position: [0, 0.613, 0], parent: root });

  // Glowing cyan pressure status indicator on front face (+X)
  createPart('PressureStatusLed', cylinderGeo(0.007, 0.007, 0.008, 6), m.glowCool, {
    position: [0.064, 0.588, 0],
    rotation: [0, 0, 90],
    parent: root
  });

  defineBudget({ triangles: BUDGETS['small-prop'] }, root);
  return root;
}
